css:
.fm-drill { font-size: 11px; }
.fm-drill__title { margin: 0; font-size: 18px; }
.fm-drill__sub { margin: 2px 0 14px; color: #555; }
.fm-drill h3 { font-size: 12px; margin: 16px 0 6px; border-bottom: 1px solid #ddd; padding-bottom: 3px; }
.fm-drill__grid, .fm-drill__table, .fm-drill__sign { width: 100%; border-collapse: collapse; }
.fm-drill__grid th, .fm-drill__grid td { border: 1px solid #ddd; padding: 4px 6px; text-align: left; vertical-align: top; }
.fm-drill__grid th { width: 18%; background: #f7f7f7; font-weight: 600; }
.fm-drill__table th, .fm-drill__table td { border: 1px solid #ddd; padding: 4px 6px; text-align: left; }
.fm-drill__table thead th { background: #f7f7f7; }
.fm-drill__table .right, .fm-drill__grid .right { text-align: right; }
.fm-drill__findings { border: 1px solid #ddd; padding: 8px; min-height: 48px; white-space: pre-wrap; }
.fm-drill__sign { margin-top: 26px; }
.fm-drill__sign td { width: 50%; padding-right: 24px; color: #555; border: 0; }
.fm-drill__rule { border-bottom: 1px solid #333; height: 30px; }
.fm-drill__note { color: #666; font-size: 9px; margin-top: 10px; }
